-- venomous bites ("DC:dice"); the column is new, so add it if this database doesn't have it yet
SET @have := (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'dnd_creature' AND COLUMN_NAME = 'venom');
SET @sql := IF(@have = 0, 'ALTER TABLE `dnd_creature` ADD COLUMN `venom` VARCHAR(24) NOT NULL DEFAULT \'\'', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
-- what the casting creatures cast (tools/casters.py: "spell id[:uses a fight],...")
SET @have := (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'dnd_creature' AND COLUMN_NAME = 'spells');
SET @sql := IF(@have = 0, 'ALTER TABLE `dnd_creature` ADD COLUMN `spells` VARCHAR(128) NOT NULL DEFAULT \'\'', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
-- what creatures carry (tools/carried.py: "item:chance,...")
SET @have := (SELECT COUNT(*) FROM information_schema.COLUMNS
               WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'dnd_creature' AND COLUMN_NAME = 'carries');
SET @sql := IF(@have = 0, 'ALTER TABLE `dnd_creature` ADD COLUMN `carries` VARCHAR(160) NOT NULL DEFAULT \'\'', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
