-- zone gates: a dwarven tunnel portcullis, locked and unselectable, in the phase of the zone it guards
DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 9100198 AND 9100199;
DELETE FROM `gameobject_template_addon` WHERE `entry` BETWEEN 9100198 AND 9100199;
