-- townsfolk roles (tools/townsfolk.py): who says what, and the gift for winning them round
DROP TABLE IF EXISTS `dnd_townsfolk_role`;
CREATE TABLE `dnd_townsfolk_role` (
  `ord` INT UNSIGNED NOT NULL,
  `role` VARCHAR(32) NOT NULL,
  `keywords` VARCHAR(255) NOT NULL DEFAULT '',
  `nodes` VARCHAR(255) NOT NULL DEFAULT '',
  `money` INT UNSIGNED NOT NULL DEFAULT 0,
  `item` INT UNSIGNED NOT NULL DEFAULT 0,
  `gift` VARCHAR(255) NOT NULL DEFAULT '',
  `after_text` VARCHAR(255) NOT NULL DEFAULT '',
  `games` VARCHAR(32) NOT NULL DEFAULT '',
  `zone` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`ord`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `dnd_townsfolk_role` (`ord`, `role`, `keywords`, `nodes`, `money`, `item`, `gift`, `after_text`, `games`, `zone`) VALUES
(0, 'merchant#0', '=adlin pridedrift', '100000,100001', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Pridedrift Provisions, open till the stock runs out. Which is soon."', '', 0),
(1, 'folk#1', '=apprentice soren', '100010,100011', 500, 0, 'A few coins, given with thanks.', '"Hearth, not bear. Hearth, not bear. I\'ve got it now. Mostly."', '', 0),
(2, 'folk#2', '=balir frosthammer', '100020,100021', 500, 0, 'A few coins, given with thanks.', '"The woodpile\'s winning, but not by as much."', '', 0),
(3, 'merchant#3', '=durnan furcutter', '100030,100031', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Hides are curing. Smell\'s worse. Business is good."', '', 0),
(4, 'tinker#4', '=felix whindlebolt', '100040,100041', 1000, 0, 'A gnome\'s grateful coins.', '"Version Ten is coming along beautifully. It\'s only exploded twice."', '', 0),
(5, 'folk#5', '=grelin whitebeard', '100050,100051', 500, 0, 'A few coins, given with thanks.', '"Ninety-one winters, if I see this one out. I mean to."', '', 0),
(6, 'smith#6', '=grundel harkin', '100060,100061', 1000, 0, 'Coin from the forge, for honest work.', '"Blade\'s only as good as the arm behind it. Look after yours."', '', 0),
(7, 'tinker#7', '=hands springsprocket', '100070,100071', 1000, 0, 'A gnome\'s grateful coins.', '"Still looking for that gear, if you\'re asking. No? Fair."', '', 0),
(8, 'folk#8', '=nori pridedrift', '100080,100081', 500, 0, 'A few coins, given with thanks.', '"I\'m doing the sums. Don\'t tell Adlin I said yes so fast."', '', 0),
(9, 'smith#9', '=rybrad coldbank', '100090,100091', 1000, 0, 'Coin from the forge, for honest work.', '"The good blank\'s on the anvil. You picked it, you know."', '', 0),
(10, 'folk#10', '=sten stoutarm', '100100,100101', 500, 0, 'A few coins, given with thanks.', '"Turnips are losing. Rabbits are winning. Same as ever."', '', 0),
(11, 'tinker#11', '=wren darkspring', '100110,100111', 1000, 0, 'A gnome\'s grateful coins.', '"Still working. Still dark. Still not twice."', '', 0),
(12, 'noble#12', '=beldin steelgrill', '100120,100121', 1500, 0, 'A purse, pressed on you with official thanks.', '"Depot\'s still closed. But it\'s a more organised closed."', '', 0),
(13, 'tinker#13', '=binjy featherwhistle', '100130,100131', 1000, 0, 'A gnome\'s grateful coins.', '"The Mark Five goes forwards. Mostly. Occasionally sideways."', '', 0),
(14, 'smith#14', '=boran ironclink', '100140,100141', 1000, 0, 'Coin from the forge, for honest work.', '"Armour\'s thicker this year. You know why."', '', 0),
(15, 'tinker#15', '=captured leper gnome', '100150,100151', 1000, 0, 'A gnome\'s grateful coins.', '"I remember my name now. I say it to myself, so I don\'t lose it again."', '', 0),
(16, 'tinker#16', '=dannie fizzwizzle', '100160,100161', 1000, 0, 'A gnome\'s grateful coins.', '"Clicky\'s on a lead now. She\'s furious about it."', '', 0),
(17, 'merchant#17', '=gamili frosthide', '100170,100171', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Sold the ugly coat. Twice. Don\'t ask."', '', 0),
(18, 'merchant#18', '=golorn frostbeard', '100180,100181', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Roads open, I\'ll be gone like smoke. Pots and all."', '', 0),
(19, 'smith#19', '=grawn thromwyn', '100190,100191', 1000, 0, 'Coin from the forge, for honest work.', '"It sings, the new blade. Almost. Give it a week."', '', 0),
(20, 'inn#20', '=innkeeper belm', '100200,100201', 300, 4540, 'Bread for the road and a few coins from the till.', '"Room\'s warm, stew\'s hot. Ale\'s still Ragnar\'s, I\'m afraid."', 'dice,cards', 0),
(21, 'brewer#21', '=jarven thunderbrew', '100210,100211', 800, 0, 'A brewer\'s thanks, in coin.', '"Barrel nine\'s singing again. Best batch of the year."', 'drink', 0),
(22, 'folk#22', '=jordan stilwell', '100220,100221', 500, 0, 'A few coins, given with thanks.', '"Still waiting on the pass. I\'m getting used to the ale."', '', 0),
(23, 'guard#23', '=kogan forgestone', '100230,100231', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still dull. Long may it last."', '', 0),
(24, 'merchant#24', '=kreg bilmn', '100240,100241', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Thirty-nine bars of soap. Make me an offer."', '', 0),
(25, 'tinker#25', '=loslor rudge', '100250,100251', 1000, 0, 'A gnome\'s grateful coins.', '"The clock\'s ticking again. So\'s the toolbox, which is new."', '', 0),
(26, 'tinker#26', '=milli featherwhistle', '100260,100261', 1000, 0, 'A gnome\'s grateful coins.', '"Mine go up a little less now. Binjy\'s furious."', '', 0),
(27, 'guard#27', '=mountaineer dolf', '100270,100271', 0, 118, 'A healing draught from the Watch\'s stores.', '"Wolf\'s gone. Cloak\'s shut. Good day so far."', '', 0),
(28, 'tinker#28', '=ozzie togglevolt', '100280,100281', 1000, 0, 'A gnome\'s grateful coins.', '"The machine hears the snow. It doesn\'t like what it hears, but it hears it."', '', 0),
(29, 'folk#29', '=pilot bellowfiz', '100290,100291', 500, 0, 'A few coins, given with thanks.', '"Engine\'s in one piece. Neither frozen nor on fire. A good day."', '', 0),
(30, 'folk#30', '=pilot stonegear', '100300,100301', 500, 0, 'A few coins, given with thanks.', '"Still need a co-pilot. Still not paying."', '', 0),
(31, 'brewer#31', '=ragnar thunderbrew', '100310,100311', 800, 0, 'A brewer\'s thanks, in coin.', '"Another round? Of course another round."', 'drink', 0),
(32, 'tinker#32', '=razzle sprysprocket', '100320,100321', 1000, 0, 'A gnome\'s grateful coins.', '"The bag\'s empty now. I\'m making a new one. Smaller. Probably."', '', 0),
(33, 'folk#33', '=senir whitebeard', '100330,100331', 500, 0, 'A few coins, given with thanks.', '"Bears are in the hills. I\'m by the fire. That\'s how it should be."', '', 0),
(34, 'inn#34', '=tannok frosthammer', '100340,100341', 300, 4540, 'Bread for the road and a few coins from the till.', '"Tray\'s full, room\'s fuller. Same as always."', 'dice,cards', 0),
(35, 'healer#35', '=thamner pol', '100350,100351', 0, 118, 'A healing draught from the chirurgeon\'s own shelf.', '"Mind you keep that draught for when it counts."', '', 0),
(36, 'folk#36', '=tharek blackstone', '100360,100361', 500, 0, 'A few coins, given with thanks.', '"Gates are still shut. I\'m still angry. That\'s two things you can rely on."', '', 0),
(37, 'smith#37', '=thrawn boltar', '100370,100371', 1000, 0, 'Coin from the forge, for honest work.', '"Coal\'s low. Iron\'s honest. That\'s the best I can say."', '', 0),
(38, 'tinker#38', '=tog rustsprocket', '100380,100381', 1000, 0, 'A gnome\'s grateful coins.', '"It warms now. Mostly. Keep a bucket nearby."', '', 0),
(39, 'folk#39', '=yori crackhelm', '100390,100391', 500, 0, 'A few coins, given with thanks.', '"Helm\'s holding. Icicles are waiting. It\'s a war."', '', 0),
(40, 'folk#40', '=zamael lunthistle', '100400,100401', 500, 0, 'A few coins, given with thanks.', '"I whistle now, sometimes. Just in case the flowers can hear."', '', 0),
(41, 'folk#41', '=rudra amberstill', '100410,100411', 500, 0, 'A few coins, given with thanks.', '"Tea\'s still on. Still tastes of ram."', '', 0),
(42, 'smith#42', '=turuk amberstill', '100420,100421', 1000, 0, 'Coin from the forge, for honest work.', '"Edge\'ll hold through a troll. Probably two."', '', 0),
(43, 'rancher#43', '=veron amberstill', '100430,100431', 800, 0, 'A rancher\'s thanks, and a few coins.', '"The rams like you. That\'s more than they say for most."', '', 0),
(44, 'folk#44', '=yarlyn amberstill', '100440,100441', 500, 0, 'A few coins, given with thanks.', '"The lambs are drinking. The wolves are hungry. We\'ll see who wins."', '', 0),
(45, 'guard#45', '=angus', '100450,100451', 0, 118, 'A healing draught from the Watch\'s stores.', '"Shorty still thinks he\'s the better shot. Shorty\'s still wrong."', '', 0),
(46, 'smith#46', '=hegnar rumbleshot', '100460,100461', 1000, 0, 'Coin from the forge, for honest work.', '"Powder\'s dry. Barrels are full. Gnomes are kept away."', '', 0),
(47, 'guard#47', '=rifleman middlecamp', '100470,100471', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still watching. They\'re still watching back."', '', 0),
(48, 'guard#48', '=rifleman wheeler', '100480,100481', 0, 118, 'A healing draught from the Watch\'s stores.', '"Got a new joke. Still about trolls. Still terrible."', '', 0),
(49, 'guard#49', '=shorty', '100490,100491', 0, 118, 'A healing draught from the Watch\'s stores.', '"I\'m still taller. I\'m still the better shot. Angus can cope."', '', 0),
(50, 'guard#50', '=spotter klemmy', '100500,100501', 0, 118, 'A healing draught from the Watch\'s stores.', '"Gerald\'s still on his rock. I think we\'re friends now."', '', 0),
(51, 'folk#51', '=tundra macgrann', '100510,100511', 500, 0, 'A few coins, given with thanks.', '"Boar\'s on the fire. Stay for supper, if you\'re downwind."', '', 0),
(52, 'merchant#52', '=burdrak harglhelm', '100520,100521', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Pink leather\'s selling well. I don\'t understand gnomes."', '', 0),
(53, 'merchant#53', '=gretta ganter', '100530,100531', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Fish are biting. So\'s the cold."', '', 0),
(54, 'brewer#54', '=keeg gibn', '100540,100541', 800, 0, 'A brewer\'s thanks, in coin.', '"Next vintage is bolder. I\'m almost afraid of it."', 'drink', 0),
(55, 'brewer#55', '=marleth barleybrew', '100550,100551', 800, 0, 'A brewer\'s thanks, in coin.', '"Rejold\'s still wrong. I\'m still right. Ale\'s still good."', 'drink', 0),
(56, 'tinker#56', '=namdo bizzfizzle', '100560,100561', 1000, 0, 'A gnome\'s grateful coins.', '"The box still hums. I\'ve named it. I talk to it. It\'s fine."', '', 0),
(57, 'folk#57', '=onin machammar', '100570,100571', 500, 0, 'A few coins, given with thanks.', '"Quiet at the depot today. Suspicious, really."', '', 0),
(58, 'brewer#58', '=rejold barleybrew', '100580,100581', 800, 0, 'A brewer\'s thanks, in coin.', '"Hops. In ale. It\'s not complicated."', 'drink', 0),
(59, 'folk#59', '=sprok', '100590,100591', 500, 0, 'A few coins, given with thanks.', '"Still in the snow. Still hate it."', '', 0),
(60, 'folk#60', '=tristane shadowstone', '100600,100601', 500, 0, 'A few coins, given with thanks.', '"Fewer things go missing now. I\'m watching."', '', 0),
(61, 'guard#61', '=avarus kharag', '100610,100611', 0, 118, 'A healing draught from the Watch\'s stores.', '"Fence holds. Troggs are digging. Business as usual."', '', 0),
(62, 'miner#62', '=foreman stonebrow', '100620,100621', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Quarry\'s working. Slowly. But it\'s working."', '', 0),
(63, 'smith#63', '=frast dokner', '100630,100631', 1000, 0, 'Coin from the forge, for honest work.', '"I can tell a good blade now. Mostly. I check twice."', '', 0),
(64, 'brewer#64', '=kazan mogosh', '100640,100641', 800, 0, 'A brewer\'s thanks, in coin.', '"Stew\'s on. Ale\'s poured. Sit."', 'drink', 0),
(65, 'guard#65', '=lookout captain lolo longstriker', '100650,100651', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still watching the south. Still learning."', '', 0),
(66, 'miner#66', '=miner grothor', '100660,100661', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Still pick, shovel, cart. Sun\'s still yellow, I\'m told."', '', 0),
(67, 'miner#67', '=miner grumnal', '100670,100671', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Still digging the right holes. Grothor\'s still digging all of them."', '', 0),
(68, 'miner#68', '=prospector gehn', '100680,100681', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Still digging into the past. It\'s deeper than I thought."', '', 0),
(69, 'miner#69', '=quarrymaster thesten', '100690,100691', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Wall\'s getting bigger. Stone\'s still good."', '', 0),
(70, 'noble#70', '=senator mehr stonehallow', '100700,100701', 1500, 0, 'A purse, pressed on you with official thanks.', '"I\'ve written to the senate. They\'ll ignore it, but I\'ve written."', '', 0),
(71, 'noble#71', '=captain rugelfuss', '100710,100711', 1500, 0, 'A purse, pressed on you with official thanks.', '"Lake\'s held. Garrison\'s tired. Same as yesterday."', '', 0),
(72, 'guard#72', '=mountaineer barleybrew', '100720,100721', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still no free ale. Still a little bitter."', '', 0),
(73, 'guard#73', '=mountaineer cobbleflint', '100730,100731', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still guarding the lake. Fish are still laughing."', '', 0),
(74, 'guard#74', '=mountaineer gravelgaw', '100740,100741', 0, 118, 'A healing draught from the Watch\'s stores.', '"I\'ve done a night watch now! Nobody died. Not even me."', '', 0),
(75, 'guard#75', '=mountaineer kalmir', '100750,100751', 0, 118, 'A healing draught from the Watch\'s stores.', '"Poem\'s finished. It\'s about you, a bit. And snow. A lot of snow."', '', 0),
(76, 'guard#76', '=mountaineer naarh', '100760,100761', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still fish. Always fish. I\'ve accepted it."', '', 0),
(77, 'guard#77', '=mountaineer pebblebitty', '100770,100771', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still Pebblebitty. Still not biting. Mostly."', '', 0),
(78, 'guard#78', '=mountaineer tyraw', '100780,100781', 0, 118, 'A healing draught from the Watch\'s stores.', '"Fourteen miles. Fourth pair of boots. Still walking."', '', 0),
(79, 'guard#79', '=mountaineer veek', '100790,100791', 0, 118, 'A healing draught from the Watch\'s stores.', '"New game\'s going well. Tyraw\'s found a way to cheat already."', '', 0),
(80, 'guard#80', '=mountaineer wallbang', '100800,100801', 0, 118, 'A healing draught from the Watch\'s stores.', '"STILL LOUD. STILL HERE. HELLO AGAIN."', '', 0),
(81, 'guard#81', '=mountaineer zaren', '100810,100811', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still dreaming of beaches. Still standing in snow."', '', 0),
(82, 'folk#82', '=narm faulk', '100820,100821', 500, 0, 'A few coins, given with thanks.', '"Head\'s clearer. Down to one moon now. Bit disappointing."', '', 0),
(83, 'folk#83', '=pilot hammerfoot', '100830,100831', 500, 0, 'A few coins, given with thanks.', '"She\'s upright again. Flying soon. Probably."', '', 0),
(84, 'folk#84', '=thorvald deepforge', '100840,100841', 500, 0, 'A few coins, given with thanks.', '"Boat\'s ready. Lake\'s not. Waiting on the thaw."', '', 0),
(85, 'guard#85', '=holdout warrior', '100850,100851', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still holding. Always holding."', '', 0),
(86, 'if_merchant#86', '=bailey stonemantle', '100860,100861', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Your gold\'s safe. Mine too. That\'s what matters."', '', 0),
(87, 'if_merchant#87', '=barnum stonemantle', '100870,100871', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Fewer complaints today. Only two hundred."', '', 0),
(88, 'if_merchant#88', '=soleil stonemantle', '100880,100881', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Vaults are full. Nobody\'s leaving. I\'m still smiling."', '', 0),
(89, 'if_merchant#89', '=bretta goldfury', '100890,100891', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Powder\'s dry. Door\'s watched. Same as ever."', '', 0),
(90, 'if_merchant#90', '=bromiir ormsen', '100900,100901', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Plates are thick. Customers come after dark. That\'s the trade now."', '', 0),
(91, 'if_merchant#91', '=bryllia ironbrand', '100910,100911', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Last good bootlaces. Still last. Still good."', '', 0),
(92, 'if_merchant#92', '=dolman steelfury', '100920,100921', 500, 0, 'A few coins, from the merchant\'s own purse.', '"No ban yet. Selling fast while I can."', '', 0),
(93, 'if_merchant#93', '=lissyphus finespindle', '100930,100931', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Silks for show, leather for running. Business is brisk."', '', 0),
(94, 'if_inn#94', '=bruuk barleybeard', '100940,100941', 300, 4540, 'A meal on the house and a few coins from the till.', '"Sheep song\'s ready. Just in case."', 'dice,cards', 0),
(95, 'if_inn#95', '=edris barleybeard', '100950,100951', 300, 4540, 'A meal on the house and a few coins from the till.', '"Floor\'s dry. For now."', 'dice,cards', 0),
(96, 'if_inn#96', '=gwenna firebrew', '100960,100961', 300, 4540, 'A meal on the house and a few coins from the till.', '"Their ale\'s half water now. They haven\'t noticed."', 'dice,cards', 0),
(97, 'if_inn#97', '=innkeeper firebrew', '100970,100971', 300, 4540, 'A meal on the house and a few coins from the till.', '"Still full - for them. Always room for you."', 'dice,cards', 0),
(98, 'if_court#98', '=curator thorius', '100980,100981', 600, 0, 'A few coins, and a scholar\'s thanks.', '"Exhibits are safe. Mostly. I check twice a day now."', '', 0),
(99, 'if_court#99', '=high explorer magellas', '100990,100991', 600, 0, 'A few coins, and a scholar\'s thanks.', '"Still writing it all down. It\'s a long book now."', '', 0),
(100, 'if_court#100', '=royal historian archesonus', '101000,101001', 600, 0, 'A few coins, and a scholar\'s thanks.', '"Ask me about the beard. Please. Nobody ever asks about the beard."', '', 0),
(101, 'if_court#101', '=senator barin redstone', '101010,101011', 600, 0, 'A few coins, and a scholar\'s thanks.', '"I\'m still in the senate. Still watching. Still waiting."', '', 0),
(102, 'if_folk#102', '=gryth thurden', '101020,101021', 400, 0, 'A few coins, given quietly.', '"The birds are calmer. So am I. Mostly."', '', 0),
(103, 'if_gnome#103', '=high tinker mekkatorque', '101030,101031', 400, 118, 'A few coins and a draught from the refugees\' little store.', '"Still planning. Always planning. One day."', '', 0),
(104, 'if_gnome#104', '=klockmort spannerspan', '101040,101041', 400, 118, 'A few coins and a draught from the refugees\' little store.', '"The clock runs. It\'s suppertime at home right now."', '', 0),
(105, 'if_gnome#105', '=master mechanic castpipe', '101050,101051', 400, 118, 'A few coins and a draught from the refugees\' little store.', '"Still fixing kettles. But I\'ve improved them. They whistle in harmony now."', '', 0),
(106, 'if_folk#106', '=tynnus venomsprout', '101060,101061', 400, 0, 'A few coins, given quietly.', '"Still selling. Still quiet. Still not here."', '', 0),
(107, 'folk#107', '=bailor stonehand', '101070,101071', 500, 0, 'A few coins, given with thanks.', '"Cart\'s chocked. Dam\'s fine. So they tell me."', '', 0),
(108, 'guard#108', '=dakk blunderblast', '101080,101081', 0, 118, 'A healing draught from the Watch\'s stores.', '"Tunnel\'s shut. Ears are ringing. Good day."', '', 0),
(109, 'merchant#109', '=drac roughcut', '101090,101091', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Mostly boar. Always boar."', '', 0),
(110, 'merchant#110', '=greishan ironstove', '101100,101101', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Still staying put. Still missing the frogs."', '', 0),
(111, 'merchant#111', '=honni goldenoat', '101110,101111', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Rolls today. Half-loaves, really. Still warm."', '', 0),
(112, 'inn#112', '=innkeeper hearthstove', '101120,101121', 300, 4540, 'Bread for the road and a few coins from the till.', '"Fire\'s lit. Stew\'s thick. Sit."', 'dice,cards', 0),
(113, 'miner#113', '=jern hornhelm', '101130,101131', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Chart\'s better. Tunnels still moving."', '', 0),
(114, 'merchant#114', '=karm ironquill', '101140,101141', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Selling lamps. Lots of lamps. The kobolds thank me."', '', 0),
(115, 'merchant#115', '=khara deepwater', '101150,101151', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Fish are back. Dam\'s quieter. Good evening for it."', '', 0),
(116, 'noble#116', '=magistrate bluntnose', '101160,101161', 1500, 0, 'A purse, pressed on you with official thanks.', '"Still a list. Shorter now."', '', 0),
(117, 'smith#117', '=morhan coppertongue', '101170,101171', 1000, 0, 'Coin from the forge, for honest work.', '"Still talking to the anvil. It\'s warming up to me."', '', 0),
(118, 'merchant#118', '=rann flamespinner', '101180,101181', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Three red scarves in town now. Progress."', '', 0),
(119, 'folk#119', '=thorgrum borrelson', '101190,101191', 500, 0, 'A few coins, given with thanks.', '"Flights are running. Fly while you can."', '', 0),
(120, 'miner#120', '=torren squarejaw', '101200,101201', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Still arguing with Jern. Winning, mostly."', '', 0),
(121, 'inn#121', '=vidra hearthstove', '101210,101211', 300, 4540, 'Bread for the road and a few coins from the till.', '"Rush is over. Kadrell\'s on his stool. All\'s well."', 'dice,cards', 0),
(122, 'smith#122', '=vrok blunderblast', '101220,101221', 1000, 0, 'Coin from the forge, for honest work.', '"Powder\'s dry. Dakk\'s been kept away. Good day."', '', 0),
(123, 'merchant#123', '=yanni stoutheart', '101230,101231', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Socks are selling. Everyone\'s feet are cold."', '', 0),
(124, 'smith#124', '=gothor brumn', '101240,101241', 1000, 0, 'Coin from the forge, for honest work.', '"Last forge before the road. I mend what comes back."', '', 0),
(125, 'noble#125', '=chief engineer hinderweir vii', '101250,101251', 1500, 0, 'A purse, pressed on you with official thanks.', '"The dam is fine. I checked. Five times."', '', 0),
(126, 'smith#126', '=nillen andemar', '101260,101261', 1000, 0, 'Coin from the forge, for honest work.', '"Maces don\'t bounce. Remember that."', '', 0),
(127, 'merchant#127', '=aldren cordon', '101270,101271', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Shirts are selling. The dust is winning."', '', 0),
(128, 'tinker#128', '=bingles blastenheimer', '101280,101281', 1000, 0, 'A gnome\'s grateful coins.', '"New shaft\'s open. Ironband\'s only a little cross."', '', 0),
(129, 'miner#129', '=magmar fellhew', '101290,101291', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Still digging. Still arguing about what for."', '', 0),
(130, 'miner#130', '=prospector ironband', '101300,101301', 1000, 0, 'A miner\'s coin for a sharp eye.', '"Closer every day. I can feel it."', '', 0),
(131, 'smith#131', '=cliff hadin', '101310,101311', 1000, 0, 'Coin from the forge, for honest work.', '"Bows are strung. Hunters are happy."', '', 0),
(132, 'folk#132', '=daryl the youngling', '101320,101321', 500, 0, 'A few coins, given with thanks.', '"I\'m practising every day! I\'ll be a Farstrider soon!"', '', 0),
(133, 'smith#133', '=irene sureshot', '101330,101331', 1000, 0, 'Coin from the forge, for honest work.', '"Fifty paces is easy. Try a hundred."', '', 0),
(134, 'merchant#134', '=kat sampson', '101340,101341', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Leather\'s selling. Running away\'s popular."', '', 0),
(135, 'folk#135', '=kelt thomasin', '101350,101351', 500, 0, 'A few coins, given with thanks.', '"Fire\'s warm. Woods are cold. Sit a while."', '', 0),
(136, 'folk#136', '=marek ironheart', '101360,101361', 500, 0, 'A few coins, given with thanks.', '"Woods are quiet. For now."', '', 0),
(137, 'folk#137', '=vyrin swiftwind', '101370,101371', 500, 0, 'A few coins, given with thanks.', '"The young forest is growing on me. Like the dwarves."', '', 0),
(138, 'merchant#138', '=xandar goodbeard', '101380,101381', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"The squirrels say hello. I think."', '', 0),
(139, 'guard#139', '=huldar', '101390,101391', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still waiting for Thelsamar. Still on our own."', '', 0),
(140, 'folk#140', '=miran', '101400,101401', 500, 0, 'A few coins, given with thanks.', '"Someone will come. Someone always comes."', '', 0),
(141, 'guard#141', '=mountaineer kadrell', '101410,101411', 0, 118, 'A healing draught from the Watch\'s stores.', '"Twenty-one years. Still here. Still not sitting anywhere but my stool."', '', 0),
(142, 'guard#142', '=thelsamar mountaineer', '101420', 0, 118, 'A healing draught from the Watch\'s stores.', '"It\'s Bram. You remembered. That\'s something."', '', 0),
(143, 'guard#143', '=mountaineer bludd', '101430', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still not getting wounded. Still Bludd."', '', 0),
(144, 'guard#144', '=mountaineer cragg', '101440', 0, 118, 'A healing draught from the Watch\'s stores.', '"Ankles are holding. Stones are watching."', '', 0),
(145, 'guard#145', '=mountaineer dalk', '101450', 0, 118, 'A healing draught from the Watch\'s stores.', '"No boar today. I can smell myself again. It\'s not much better."', '', 0),
(146, 'guard#146', '=mountaineer droken', '101460', 0, 118, 'A healing draught from the Watch\'s stores.', '"Dam groaned again last night. Quieter. I think."', '', 0),
(147, 'guard#147', '=mountaineer fazgard', '101470', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still singing. Troggs still avoiding me."', '', 0),
(148, 'guard#148', '=mountaineer gwarth', '101480', 0, 118, 'A healing draught from the Watch\'s stores.', '"Fence is mended. Axe is only a little shiny today."', '', 0),
(149, 'guard#149', '=mountaineer harn', '101490', 0, 118, 'A healing draught from the Watch\'s stores.', '"Thirty-three springs. Next spring I\'ll retire. Maybe."', '', 0),
(150, 'guard#150', '=mountaineer janha', '101500', 0, 118, 'A healing draught from the Watch\'s stores.', '"The goat came back. It likes you. I\'m sorry."', '', 0),
(151, 'guard#151', '=mountaineer kamdar', '101510', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still running. Still mostly awake."', '', 0),
(152, 'guard#152', '=mountaineer langarr', '101520', 0, 118, 'A healing draught from the Watch\'s stores.', '"Five fires tonight. Better than six."', '', 0),
(153, 'guard#153', '=mountaineer modax', '101530', 0, 118, 'A healing draught from the Watch\'s stores.', '"Chapter twelve. The dam almost collapsed a fourth time."', '', 0),
(154, 'guard#154', '=mountaineer ozmok', '101540', 0, 118, 'A healing draught from the Watch\'s stores.', '"No more wasps. I promise. Probably."', '', 0),
(155, 'guard#155', '=mountaineer roghan', '101550', 0, 118, 'A healing draught from the Watch\'s stores.', '"She remembers you. Tail\'s wagging."', '', 0),
(156, 'guard#156', '=mountaineer stenn', '101560', 0, 118, 'A healing draught from the Watch\'s stores.', '"Axe is on my belt. Tied on. Twice."', '', 0),
(157, 'guard#157', '=mountaineer swarth', '101570', 0, 118, 'A healing draught from the Watch\'s stores.', '"Bells are set. Troggs are screaming. Good day."', '', 0),
(158, 'guard#158', '=mountaineer uthan', '101580', 0, 118, 'A healing draught from the Watch\'s stores.', '"Forty-two sheep. All accounted for. I count them twice."', '', 0),
(159, 'guard#159', '=mountaineer wuar', '101590', 0, 118, 'A healing draught from the Watch\'s stores.', '"Fence is finished. Every stake sharp. Let them come."', '', 0),
(160, 'guard#160', '=mountaineer angst', '101600', 0, 118, 'A healing draught from the Watch\'s stores.', '"Dam\'s creaking less. Mood\'s better. Name\'s the same."', '', 0),
(161, 'guard#161', '=mountaineer barn', '101610', 0, 118, 'A healing draught from the Watch\'s stores.', '"Got a new joke. It\'s about a barn. Obviously."', '', 0),
(162, 'guard#162', '=mountaineer morlic', '101620', 0, 118, 'A healing draught from the Watch\'s stores.', '"Dam\'s fine. I checked too."', '', 0),
(163, 'guard#163', '=mountaineer haggil', '101630', 0, 118, 'A healing draught from the Watch\'s stores.', '"Haggis laughed. Once. I\'ll treasure it."', '', 0),
(164, 'guard#164', '=mountaineer haggis', '101640', 0, 118, 'A healing draught from the Watch\'s stores.', '"New joke\'s ready. Tomorrow morning. He won\'t know what hit him."', '', 0),
(165, 'guard#165', '=mountaineer brokk', '101650', 0, 118, 'A healing draught from the Watch\'s stores.', '"Road\'s open-ish. Still holding this end."', '', 0),
(166, 'guard#166', '=mountaineer hammerfall', '101660', 0, 118, 'A healing draught from the Watch\'s stores.', '"Nobody\'s asked about statues today. A good day."', '', 0),
(167, 'guard#167', '=mountaineer luxst', '101670', 0, 118, 'A healing draught from the Watch\'s stores.', '"Slept four hours. Best sleep since the thaw."', '', 0),
(168, 'guard#168', '=mountaineer morran', '101680', 0, 118, 'A healing draught from the Watch\'s stores.', '"Letters went north. A few came back. Life goes on."', '', 0),
(169, 'guard#169', '=mountaineer yuttha', '101690', 0, 118, 'A healing draught from the Watch\'s stores.', '"Stew\'s on. Boots are mended. Reports are late."', '', 0),
(170, 'guard#170', '=mountaineer zwarn', '101700', 0, 118, 'A healing draught from the Watch\'s stores.', '"Catching up on Brokk. The ale\'s mine this month."', '', 0),
(171, 'guard#171', '=mountaineer stormpike', '101710', 0, 118, 'A healing draught from the Watch\'s stores.', '"Still holding Loch Modan. The debt\'s nearly paid."', '', 0),
(172, 'guard#172', '=mountaineer rockgar', '101720', 0, 118, 'A healing draught from the Watch\'s stores.', '"Looked over the edge twice today. Still hate it."', '', 0),
(173, 'guard#173', '=mountaineer ganin', '101730', 0, 118, 'A healing draught from the Watch\'s stores.', '"The ram remembers you. She hasn\'t bitten anyone today."', '', 0),
(174, 'guard#174', '=mountaineer flint', '101740', 0, 118, 'A healing draught from the Watch\'s stores.', '"Beacon\'s dry. No false alarms. No boar duty."', '', 0),
(175, 'harbor_sailor#175', '=bart tidewater', '101750,101751', 600, 0, 'A sailor\'s tip, and a coin for luck.', '"Still waiting on the weather. Still alive. That\'s sailing."', '', 0),
(176, 'harbor_sailor#176', '=first mate fitzsimmons', '101760,101761', 600, 0, 'A sailor\'s tip, and a coin for luck.', '"Deck\'s clean. Crew\'s calm. For an hour."', '', 0),
(177, 'harbor_sailor#177', '=ludin farrow', '101770,101771', 600, 0, 'A sailor\'s tip, and a coin for luck.', '"Ledger balances today. A small miracle."', '', 0),
(178, 'harbor_merchant#178', '=stuart fleming', '101780,101781', 500, 0, 'A few coins, from the trader\'s own purse.', '"Fish are coming back. Slowly."', '', 0),
(179, 'harbor_folk#179', '=shellei brondir', '101790,101791', 500, 0, 'A few coins, given with thanks.', '"Birds are dry. For now. It\'s raining again."', '', 0),
(180, 'harbor_folk#180', '=unger statforth', '101800,101801', 500, 0, 'A few coins, given with thanks.', '"The colt\'s taking a saddle. Slowly."', '', 0),
(181, 'harbor_folk#181', '=james halloran', '101810,101811', 500, 0, 'A few coins, given with thanks.', '"Nets are mended. Children are fed. A good day."', '', 0),
(182, 'harbor_folk#182', '=regina halloran', '101820,101821', 500, 0, 'A few coins, given with thanks.', '"Washing\'s dry. First time all month."', '', 0),
(183, 'harbor_folk#183', '=andrea halloran', '101830,101831', 500, 0, 'A few coins, given with thanks.', '"I practise every day! I\'m getting good!"', '', 0),
(184, 'harbor_folk#184', '=jesse halloran', '101840,101841', 500, 0, 'A few coins, given with thanks.', '"Andrea still hasn\'t found my spot. Shh."', '', 0),
(185, 'harbor_inn#185', '=innkeeper helbrek', '101850,101851', 300, 4540, 'Bread for the road and a few coins from the till.', '"Floors are muddy. Rooms are full. Ale\'s cold."', 'dice,cards', 0),
(186, 'harbor_inn#186', '=mikhail', '101860,101861', 300, 4540, 'Bread for the road and a few coins from the till.', '"Bilge rum\'s flowing. Sailors are singing."', 'dice,cards', 0),
(187, 'harbor_guard#187', '=captain stoutfist', '101870,101871', 0, 118, 'A healing draught from the watch\'s stores.', '"Harbour\'s held. Another day."', '', 0),
(188, 'harbor_guard#188', '=hargin mundar', '101880,101881', 0, 118, 'A healing draught from the watch\'s stores.', '"Caught two smugglers this week. A record."', '', 0),
(189, 'harbor_merchant#189', '=brahnmar', '101890,101891', 500, 0, 'A few coins, from the trader\'s own purse.', '"Oil your mail. Every night. Trust me."', '', 0),
(190, 'harbor_merchant#190', '=brak durnad', '101900,101901', 500, 0, 'A few coins, from the trader\'s own purse.', '"Blades are sharp. Orcs are wary."', '', 0),
(191, 'harbor_merchant#191', '=murndan derth', '101910,101911', 500, 0, 'A few coins, from the trader\'s own purse.', '"Selling oilskins now. Finally."', '', 0),
(192, 'harbor_merchant#192', '=naela trance', '101920,101921', 500, 0, 'A few coins, from the trader\'s own purse.', '"Bows are strung. Derth\'s still selling clubs."', '', 0),
(193, 'harbor_merchant#193', '=edwina monzor', '101930,101931', 500, 0, 'A few coins, from the trader\'s own purse.', '"Arrows by the sheaf. Sentries still shooting shadows."', '', 0),
(194, 'harbor_merchant#194', '=gruham rumdnul', '101940,101941', 500, 0, 'A few coins, from the trader\'s own purse.', '"Rain capes are selling. It\'s raining."', '', 0),
(195, 'harbor_folk#195', '=derina rumdnul', '101950,101951', 500, 0, 'A few coins, given with thanks.', '"Cellar\'s dry. For now. Don\'t tell the rain."', '', 0),
(196, 'harbor_folk#196', '=gimlok rumdnul', '101960,101961', 500, 0, 'A few coins, given with thanks.', '"Fixed six roofs this week. All leaking again."', '', 0),
(197, 'harbor_healer#197', '=dewin shimmerdawn', '101970,101971', 0, 118, 'A healing draught from the apothecary\'s shelf.', '"Remedy\'s working. Fewer fevers."', '', 0),
(198, 'harbor_merchant#198', '=falkan armonis', '101980,101981', 500, 0, 'A few coins, from the trader\'s own purse.', '"Jars are labelled properly now. Mostly."', '', 0),
(199, 'harbor_merchant#199', '=jennabink powerseam', '101990,101991', 500, 0, 'A few coins, from the trader\'s own purse.', '"All legal now. Mostly."', '', 0),
(200, 'harbor_merchant#200', '=kersok prond', '102000,102001', 500, 0, 'A few coins, from the trader\'s own purse.', '"Crocolisk hides are selling. Hunters are scarce."', '', 0),
(201, 'harbor_merchant#201', '=neal allen', '102010,102011', 500, 0, 'A few coins, from the trader\'s own purse.', '"Lantern works in heavy rain now. A first."', '', 0),
(202, 'harbor_folk#202', '=camerick jongleur', '102020,102021', 500, 0, 'A few coins, given with thanks.', '"Twenty verses now. The fisherman has a sequel."', '', 0),
(203, 'harbor_folk#203', '=caitlin grassman', '102030,102031', 500, 0, 'A few coins, given with thanks.', '"Still waiting. The letter\'s on its way, at least."', '', 0),
(204, 'harbor_folk#204', '=harlo barnaby', '102040,102041', 500, 0, 'A few coins, given with thanks.', '"Saw the lights again last night. I swear it."', '', 0),
(205, 'harbor_folk#205', '=junder brokk', '102050,102051', 500, 0, 'A few coins, given with thanks.', '"Storehouse is dry. Town\'s still sinking."', '', 0),
(206, 'harbor_folk#206', '=glorin steelbrow', '102060,102061', 500, 0, 'A few coins, given with thanks.', '"Caught a fish. A small one. Still counts."', '', 0),
(207, 'harbor_folk#207', '=red jack flint', '102070,102071', 500, 0, 'A few coins, given with thanks.', '"Another hand? I\'ve a new story."', '', 0),
(208, 'harbor_folk#208', '=karl boran', '102080,102081', 500, 0, 'A few coins, given with thanks.', '"Door shuts. Until next month."', '', 0),
(209, 'harbor_folk#209', '=murphy west', '102090,102091', 500, 0, 'A few coins, given with thanks.', '"Barn\'s planned. Just need the orcs gone."', '', 0),
(210, 'harbor_folk#210', '=samor festivus', '102100,102101', 500, 0, 'A few coins, given with thanks.', '"Still selling. Still quiet. Still not here."', '', 0),
(211, 'harbor_folk#211', '=sida', '102110,102111', 500, 0, 'A few coins, given with thanks.', '"The fire\'s still lit. Always will be."', '', 0),
(212, 'harbor_folk#212', '=tapoke "slim" jahn', '102120,102121', 500, 0, 'A few coins, given with thanks.', '"Know anything new? I\'m buying."', '', 0),
(213, 'harbor_folk#213', '=thomas booker', '102130,102131', 500, 0, 'A few coins, given with thanks.', '"Writing letters. Lots of letters. The ships are sailing soon."', '', 0),
(214, 'harbor_folk#214', '=timothy clark', '102140,102141', 500, 0, 'A few coins, given with thanks.', '"Lamps are lit. The fog\'s winning, but slower."', '', 0),
(215, 'harbor_folk#215', '=valstag ironjaw', '102150,102151', 500, 0, 'A few coins, given with thanks.', '"Jaw\'s oiled. Grinning\'s easier now."', '', 0),
(216, 'harbor_folk#216', '=vincent hyal', '102160,102161', 500, 0, 'A few coins, given with thanks.', '"Caught the cat. We\'re friends now. He still steals fish."', '', 0),
(217, 'harbor_folk#217', '=adam lind', '102170,102171', 500, 0, 'A few coins, given with thanks.', '"Light\'s on. Admiral\'s sulking on the roof."', '', 0),
(218, 'harbor_folk#218', '=tarrel rockweaver', '102180,102181', 500, 0, 'A few coins, given with thanks.', '"Merrin wrote. She\'s fine. She says I worry too much. I do."', '', 0),
(219, 'harbor_folk#219', '=archaeologist flagongut', '102190,102191', 500, 0, 'A few coins, given with thanks.', '"Crates are dry. Still waiting for a ship."', '', 0),
(220, 'harbor_folk#220', '=merrin rockweaver', '102200,102201', 500, 0, 'A few coins, given with thanks.', '"Dig\'s going well. Tell Tarrel I\'m fine."', '', 0),
(221, 'harbor_folk#221', '=ormer ironbraid', '102210,102211', 500, 0, 'A few coins, given with thanks.', '"Fire\'s high. Reeds are quiet. For now."', '', 0),
(222, 'harbor_folk#222', '=prospector whelgar', '102220,102221', 500, 0, 'A few coins, given with thanks.', '"The old fish is safe. Ironforge will love him."', '', 0),
(223, 'harbor_folk#223', '=ashlan stonesmirk', '102230,102231', 500, 0, 'A few coins, given with thanks.', '"Still smirking. Still holding the bridge."', '', 0),
(224, 'harbor_folk#224', '=longbraid the grim', '102240,102241', 500, 0, 'A few coins, given with thanks.', '"Still watching. Still grim. But less alone."', '', 0),
(225, 'harbor_folk#225', '=motley garmason', '102250,102251', 500, 0, 'A few coins, given with thanks.', '"Bridge Stout\'s flowing. Rhag\'s still wrong."', '', 0),
(226, 'harbor_folk#226', '=rhag garmason', '102260,102261', 500, 0, 'A few coins, given with thanks.', '"Motley\'s stout is still terrible. I love him anyway."', '', 0),
(227, 'harbor_folk#227', '=roggo harlbarrow', '102270,102271', 500, 0, 'A few coins, given with thanks.', '"Four turnips this week. A record."', '', 0),
(228, 'harbor_folk#228', '=foggy mackreel', '102280,102281', 500, 0, 'A few coins, given with thanks.', '"Hello! Have we met? Doesn\'t matter. Hello."', '', 0),
(229, 'harbor_folk#229', '=comar villard', '102290,102291', 500, 0, 'A few coins, given with thanks.', '"Still watching. They\'re still digging."', '', 0),
(230, 'harbor_folk#230', '=dark iron entrepreneur', '102300,102301', 500, 0, 'A few coins, given with thanks.', '"Still selling. Still not a spy. Probably."', '', 0),
(231, 'harbor_folk#231', '=einar stonegrip', '102310,102311', 500, 0, 'A few coins, given with thanks.', '"New path\'s working. Still sweating."', '', 0),
(232, 'harbor_folk#232', '=fradd swiftgear', '102320,102321', 500, 0, 'A few coins, given with thanks.', '"Pump works. Mostly mud-free."', '', 0),
(233, 'harbor_folk#233', '=wenna silkbeard', '102330,102331', 500, 0, 'A few coins, given with thanks.', '"Silks are dry. Fradd\'s broken the pump again."', '', 0),
(234, 'harbor_folk#234', '=terl arakor', '102340,102341', 500, 0, 'A few coins, given with thanks.', '"Fewer raptors this week. Still too many."', '', 0),
(235, 'harbor_guard#235', '=mounted ironforge mountaineer', '102350,102351', 0, 118, 'A healing draught from the watch\'s stores.', '"Road\'s clear. Riding again at dusk."', '', 0),
(236, 'refuge_guard#236', '=commander amaren', '102360,102361', 0, 118, 'A healing draught from the camp\'s stores.', '"The Pointe holds. Another day."', '', 0),
(237, 'refuge_guard#237', '=captain nials', '102370,102371', 0, 118, 'A healing draught from the camp\'s stores.', '"Patrols are coming back whole. Mostly."', '', 0),
(238, 'refuge_folk#238', '=apprentice kryten', '102380,102381', 500, 0, 'A few coins, given with thanks.', '"Ward\'s holding. No flickers today."', '', 0),
