(375, 'el_folk#375', '=tommy joe stonefield', '103750,103751', 400, 0, 'A few coins, given quietly.', '"Got my stone back. Billy\'s sulking."', '', 0),
(376, 'el_folk#376', '=pa maclure', '103760,103761', 400, 0, 'A few coins, given quietly.', '"Fence is mended. Feud\'s not."', '', 0),
(377, 'el_folk#377', '=maybell maclure', '103770,103771', 400, 0, 'A few coins, given quietly.', '"Tommy Joe wrote back. Don\'t tell Pa."', '', 0),
(378, 'el_folk#378', '=billy maclure', '103780,103781', 400, 0, 'A few coins, given quietly.', '"Gave the stone back. Kept the frog."', '', 0),
(379, 'el_merchant#379', '=joshua maclure', '103790,103791', 500, 0, 'A few coins, from the trader\'s own purse.', '"Wine\'s good. Stonefields still make nothing."', '', 0),
(380, 'el_folk#380', '=gerard tiller', '103800,103801', 400, 0, 'A few coins, given quietly.', '"Still working both farms. Still a secret."', '', 0),
(381, 'el_folk#381', '=farmer furlbrow', '103810,103811', 400, 0, 'A few coins, given quietly.', '"Planning to rebuild. One day."', '', 0),
(382, 'el_folk#382', '=verna furlbrow', '103820,103821', 400, 0, 'A few coins, given quietly.', '"Found my mother\'s locket in the ashes. A small mercy."', '', 0),
(383, 'el_guard#383', '=deputy rainer', '103830,103831', 0, 118, 'A healing draught from the garrison\'s chest.', '"Gnolls are quiet. For tonight."', '', 0),
(384, 'el_merchant#384', '=quartermaster hicks', '103840,103841', 500, 0, 'A few coins, from the trader\'s own purse.', '"Stock\'s counted. Still short."', '', 0),
(385, 'el_merchant#385', '=quartermaster hudson', '103850,103851', 500, 0, 'A few coins, from the trader\'s own purse.', '"Mending plate. Always mending."', '', 0),
(386, 'el_guard#386', '=sergeant de vries', '103860,103861', 0, 118, 'A healing draught from the garrison\'s chest.', '"Morale\'s up. Cake helped."', '', 0),
(387, 'el_merchant#387', '=veldan lightfoot', '103870,103871', 500, 0, 'A few coins, from the trader\'s own purse.', '"Scouts are buying. Gnolls are sniffing."', '', 0),
(388, 'el_folk#388', '=theocritus', '103880,103881', 400, 0, 'A few coins, given quietly.', '"Working in peace. Selling what I please."', '', 0),
(389, 'el_merchant#389', '=dawn brightstar', '103890,103891', 500, 0, 'A few coins, from the trader\'s own purse.', '"Everything\'s labelled now. Mostly."', '', 0),
(390, 'el_merchant#390', '=morley eberlein', '103900,103901', 500, 0, 'A few coins, from the trader\'s own purse.', '"More pockets this season. Mages are pleased."', '', 0),
(391, 'el_guard#391', '=supervisor raelen', '103910,103911', 0, 118, 'A healing draught from the garrison\'s chest.', '"Camp\'s held. Timber\'s flowing."', '', 0),
(392, 'el_merchant#392', '=terry palin', '103920,103921', 500, 0, 'A few coins, from the trader\'s own purse.', '"Trees falling where they should. Mostly."', '', 0),
(393, 'el_folk#393', '=sara timberlain', '103930,103931', 400, 0, 'A few coins, given quietly.', '"Stew\'s hot. Camp\'s happier."', '', 0),
(394, 'el_guard#394', '=guard thomas', '103940,103941', 0, 118, 'A healing draught from the garrison\'s chest.', '"Bridge held. No murlocs crossed."', '', 0),
(395, 'el_merchant#395', '=antonio perelli', '103950,103951', 500, 0, 'A few coins, from the trader\'s own purse.', '"Still selling. Still not selling the hat."', '', 0),
(396, 'el_folk#396', '=henze faulk', '103960,103961', 400, 0, 'A few coins, given quietly.', '"Leg\'s better. Walking soon."', '', 0),
(397, 'tinker#p0', '=gnomeregan evacuee', '150000,150005,150010,150015,150001,150006,150011,150016', 1000, 0, 'A gnome\'s grateful coins.', '"Thank you. Truly. We\'ll manage. We always do."', '', 0),
(398, 'folk#p1', '=slave worker', '150050,150055,150060,150065,150070,150075,150051,150056,150061,150066,150071,150076', 500, 0, 'A few coins, given with thanks.', '"...Go. Before they see you talking to me."', '', 0),
(399, 'if_guard#p2', '=ironforge guard', '150100,150105,150110,150115,150120,150125,150130,150135,150101,150106,150111,150116,150121,150126,150131,150136', 0, 118, 'A healing draught from the guardhouse, passed over quietly.', '"For the king. The real one."', '', 0),
