(409, 'refuge_guard#p12', '=stromgarde vindicator', '150600,150605,150610,150615,150620,150625,150601,150606,150611,150616,150621,150626', 0, 118, 'A healing draught from the camp\'s stores.', '"The Light keeps us."', '', 0),
(410, 'refuge_guard#p13', '=stromgarde cavalryman', '150650,150655,150651,150656', 0, 118, 'A healing draught from the camp\'s stores.', '"Ride well."', '', 0),
