(414, 'el_guard#p17', '=northshire guard', '150850,150855,150860,150865,150870,150875,150851,150856,150861,150866,150871,150876', 0, 118, 'A healing draught from the garrison\'s chest.', '"Light keep you."', '', 0),
(415, 'el_folk#p18', '=northshire peasant', '150900,150905,150910,150915,150920,150901,150906,150911,150916,150921', 400, 0, 'A few coins, given quietly.', '"Good day."', '', 0),
(416, 'el_folk#p19', '=eastvale peasant', '150950,150955,150960,150965,150970,150951,150956,150961,150966,150971', 400, 0, 'A few coins, given quietly.', '"Good day."', '', 0),
(417, 'el_merchant#p20', '=eastvale lumberjack', '151000,151005,151010,151001,151006,151011', 500, 0, 'A few coins, from the trader\'s own purse.', '"Timber!"', '', 0),
(418, 'guard:327', 'sergeant hilde brassjaw', '9000', 0, 118, 'A healing draught from the sergeant\'s own belt.', '"Back again? Good. Means you\'re still breathing."', '', 0),
(419, 'guard:329', 'old tam kettlebeard', '9020', 600, 0, 'A few coins - Tam\'s winnings from a card game he swears he didn\'t cheat at.', '"Ah, it\'s you. Come to hear the rest of the story? No? Pity."', '', 0),
(420, 'guard:353', 'brenna stoutvale', '9040', 0, 2139, 'Brenna\'s spare belt knife - a plain, well-kept dagger.', '"Road\'s quiet today. Let\'s keep it that way."', '', 0),
(421, 'guard:410', 'corporal durn ashgrip', '9060', 900, 0, 'Durn\'s share of a toll the Watch hasn\'t been collecting.', '"Hearth\'s still lit. I checked."', '', 0),
(422, 'guard:291', 'gorrim flintwhistle', '9080', 0, 118, 'A healing draught, from Gorrim\'s \'emergency\' pouch.', '"Still alive! Told you the road was the safe part."', '', 0),
(423, 'guard:229', 'mira coldforge', '9100', 1200, 0, 'Mira\'s bounty money for a trogg she says you basically caught.', '"Any more trogg sign on your travels? No? Good."', '', 0),
(424, 'guard:212', 'captain bolvar thaneshield', '9120', 2000, 0, 'Watch pay, for an irregular the captain has decided to recognise.', '"Irregular. Good to see you."', '', 0),
(425, 'guard:4133', 'ysolde granitebrow', '9140', 0, 2504, 'Ysolde\'s old hunting bow. She has a better one.', '"Keep your bowstring dry."', '', 0),
(426, 'guard:4479', 'brannoc ironsong', '9160', 0, 858, 'A potion of greater healing - Brannoc\'s last.', '"The road east is still shut, friend. For now."', '', 0),
(427, 'guard:4067', 'kessa hammerfall', '9180', 0, 2134, 'A handaxe from the depot stores, no questions asked.', '"Depot\'s still standing. Thanks for asking."', '', 0),
(428, 'guard:150', 'dagran stonefist', '9200', 700, 0, 'Dagran\'s wager - a bet he lost fair and square.', '"Arm\'s still sore. Don\'t gloat."', '', 0),
(429, 'guard:2283', 'pell brightanvil', '9220', 500, 118, 'A healing draught and a few coins from Pell\'s patrol pay.', '"Same loop, same snow. Wouldn\'t have it any other way. Would have it SLIGHTLY other ways."', '', 0),
(430, 'guard:161007', 'hrodar the watcher', '9240', 1500, 0, 'A bag of coins Hrodar says the mountain gave him.', '"The mountain remembers you."', '', 0),
(431, 'guard:145', 'warden torvald grimbrand', '9260', 0, 2362, 'A Watch shield, slightly dented, entirely serviceable.', '"Mind the Dark Irons inside. They mind you."', '', 0),
(432, 'guard:140', 'warden brodd ironhelm', '9280', 0, 118, 'A healing draught from the gatehouse stores.', '"Still standing. For now."', '', 0),
(433, 'guard:4471', 'aldrena frostbeard', '9300', 0, 118, 'A healing draught, with the camp\'s thanks.', '"Camp\'s holding. You helped."', '', 0),
(434, 'guard:4159', 'olgar deepbarrel', '9320', 800, 0, 'Olgar\'s \'tax\' on passing travellers, returned with interest.', '"Road\'s yours, friend. No toll for you."', '', 0),
(435, 'guard:6336', 'gilda stormhammer', '9340', 0, 15807, 'A light crossbow from the post\'s armoury.', '"Loch Modan waits beyond the hills. Earn it."', '', 0),
(436, 'guard:3028', 'borin icewater', '9360', 1000, 0, 'Coins from the bottom of the lake. Borin\'s fishing has its rewards.', '"Fish are biting! ...No they\'re not."', '', 0),
(437, 'guard:6358', 'ragna steelbrow', '9380', 0, 2130, 'A mace from Ragna\'s own kit.', '"Hold the line, friend."', '', 0),
(438, 'harbor_healer', 'physician,chirurgeon,healer,priest,alchemy,apothecary', '9400,9401', 0, 118, 'A healing draught from the apothecary\'s shelf.', '"Keep your feet dry and that draught handy."', '', 11),
(439, 'harbor_inn', 'innkeeper,tavern,barmaid,potboy,cook', '9420,9421', 300, 4540, 'Bread for the road and a few coins from the till.', '"Fire\'s lit and the stew\'s fish. It\'s always fish."', 'dice,cards', 11),
(440, 'harbor_sailor', 'sailor,first mate,captain,crewman,dock,fisher,harbor,quartermaster,navigator', '9440,9441', 600, 0, 'A sailor\'s tip, and a coin for luck.', '"Fair winds to you."', '', 11),
(441, 'harbor_guard', 'sentry,guard,watch,mountaineer,rifleman', '9460,9461', 0, 118, 'A healing draught from the watch\'s stores.', '"Stay out of the hills after dark."', '', 11),
(442, 'harbor_merchant', 'provisioner,tanner,peddler,supplies,merchant,goods,trader,clothier,baker,trade', '9480,9481', 500, 0, 'A few coins, from the trader\'s own purse.', '"Come back when the ships do."', '', 11),
(443, 'harbor_folk', '*', '9500,9501', 500, 0, 'A few coins, given with thanks.', '"Mind the bog."', '', 11),
(444, 'refuge_guard', 'defender,captain,commander,sentry,guard,marshal,sergeant,elite', '9520,9521', 0, 118, 'A healing draught from the camp\'s stores.', '"Keep your back to the wall out there."', '', 45),
(445, 'refuge_merchant', 'supplies,goods,butcher,macecrafter,tradesman,merchant,trader,alchemy,leatherworking', '9540,9541', 500, 0, 'A few coins, from the trader\'s own purse.', '"Come back alive - I want your custom."', '', 45),
(446, 'refuge_folk', '*', '9560,9561', 500, 0, 'A few coins, given with thanks.', '"Light keep you, out there."', '', 45),
(447, 'thorium_guard', 'lookout,captain,sentry,guard', '9580,9581', 0, 118, 'A healing draught from the Brotherhood\'s stores.', '"Keep your head below the ridgeline."', '', 51),
(448, 'thorium_smith', 'smith,heavyhands,sootsmoker,taskmaster,overseer,merchant', '9600,9601', 500, 0, 'A few coins, and a smith\'s nod.', '"Mind the slag on the way out."', '', 51),
(449, 'thorium_folk', '*', '9620,9621', 500, 0, 'A few coins, given gruffly.', '"Watch the Cauldron."', '', 51),
(450, 'if_guard', 'gate warden,guard,warden', '9640,9641', 0, 118, 'A healing draught from the guardhouse, passed over quietly.', '"For the king. The real one."', '', 1537),
(451, 'if_inn', 'innkeeper,barmaid,bartender,tavern', '9660,9661', 300, 4540, 'A meal on the house and a few coins from the till.', '"Keep your head down and your mug full."', 'dice,cards', 1537),
(452, 'if_merchant', 'merchant,goods,banker,dealer,armor,weapon,gun', '9680,9681', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Come back while there\'s still a market."', '', 1537),
(453, 'if_court', 'explorer,curator,historian,senator,librarian,league', '9700,9701', 600, 0, 'A few coins, and a scholar\'s thanks.', '"History is watching us. Do try to behave."', '', 1537),
(454, 'if_gnome', 'tinker,mechanic,gnome,king of gnomes,citizen,mekkatorque,klockmort', '9720,9721', 400, 118, 'A few coins and a draught from the refugees\' little store.', '"Mind the gears!"', '', 1537),
(455, 'if_folk', '*', '9740,9741', 400, 0, 'A few coins, given quietly.', '"Keep your head down."', '', 1537),
(456, 'sw_guard', 'guard,officer,major,watch', '9760,9761', 0, 118, 'A healing draught from the guardhouse, slipped across.', '"Light keep you. Somebody has to."', '', 1519),
(457, 'sw_inn', 'innkeeper,barmaid,bartender,tavern,barkeep', '9780,9781', 300, 4540, 'A meal on the house and a few coins from the till.', '"Mind how you go - and mind who\'s listening."', 'dice,cards', 1519),
(458, 'sw_merchant', 'merchant,goods,banker,supplies,vendor,dealer,gun,bow,armor,cheese,florist,wine,clothier,cobbler', '9800,9801', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Come back while there\'s still a market."', '', 1519),
(459, 'sw_court', 'bishop,brother,nurse,count,lord,librarian,architect,archmage,sorcerer,priest,acolyte', '9820,9821', 600, 0, 'A few coins, and a scholar\'s - or a priest\'s - thanks.', '"The Light watches, even here. Especially here."', '', 1519),
(460, 'sw_dwarf', 'longbeard,elmore,brohann,thistlenettle,league,deepforge,axehand,flintcrag', '9840,9841', 400, 118, 'A few coins and a draught from the dwarves\' own store.', '"Mind yourself, lad - or lass. Mind yourself."', '', 1519),
(461, 'sw_folk', '*', '9860,9861', 400, 0, 'A few coins, given quietly.', '"Keep your head down."', '', 1519),
(462, 'el_inn', 'innkeeper,barkeep,bartender,cook,butcher', '9880,9881', 300, 4540, 'A meal on the house and a few coins from the till.', '"Mind the roads. Mind the Defias. Mind your purse."', 'dice,cards', 12),
(463, 'el_merchant', 'merchant,supplies,weaponsmith,armorer,bowyer,physician,lumberjack,breeder,trade', '9900,9901', 500, 0, 'A few coins, from the trader\'s own purse.', '"Safe roads, if there are any."', '', 12),
(464, 'el_guard', 'guard,marshal,deputy,sergeant,quartermaster,officer', '9920,9921', 0, 118, 'A healing draught from the garrison\'s chest.', '"Stay on the road. And stay alive."', '', 12),
(465, 'el_abbey', 'brother,priestess,librarian,paxton,neals', '9940,9941', 600, 0, 'A few coins and the Abbey\'s blessing.', '"The Light go with you on the road."', '', 12),
(466, 'el_folk', '*', '9960,9961', 400, 0, 'A few coins, given quietly.', '"Mind the roads."', '', 12),
(467, 'healer', 'physician,chirurgeon,healer,priest', '9980,9985,9990,9995,9981,9986,9991,9996', 0, 118, 'A healing draught from the chirurgeon\'s own shelf.', '"Mind you keep that draught for when it counts."', '', 0),
(468, 'inn', 'innkeeper,tavern,barmaid,potboy', '10000,10005,10010,10015,10001,10006,10011,10016', 300, 4540, 'Bread for the road and a few coins from the till.', '"Room\'s warm and the stew\'s hot, if you want either."', 'dice,cards', 0),
(469, 'noble', 'senator,captain,elder,depot master,magistrate,chief engineer', '10020,10025,10030,10035,10021,10026,10031,10036', 1500, 0, 'A purse, pressed on you with official thanks.', '"Carry on. And keep your eyes open out there."', '', 0),
(470, 'guard', 'mountaineer,guard,rifleman,spotter,watch,warden,lookout,sentry', '10040,10045,10050,10055,10041,10046,10051,10056', 0, 118, 'A healing draught from the Watch\'s stores.', '"Stay on the roads where you can, and keep your back to the rocks."', '', 0),
(471, 'brewer', 'brew,ale & wine,vintner,victualler,food & drink,cellar', '10060,10065,10070,10075,10061,10066,10071,10076', 800, 0, 'A brewer\'s thanks, in coin.', '"Next batch\'ll be better. They always are."', 'drink', 0),
(472, 'smith', 'smith,armorer,forge,gunsmith,bowyer,macecrafter', '10080,10085,10090,10095,10081,10086,10091,10096', 1000, 0, 'Coin from the forge, for honest work.', '"Blade\'s only as good as the arm behind it. Look after yours."', '', 0),
(473, 'rancher', 'ram,amberstill', '10100,10105,10110,10115,10101,10106,10111,10116', 800, 0, 'A rancher\'s thanks, and a few coins.', '"The rams like you. That\'s more than they say for most."', '', 0),
(474, 'miner', 'miner,prospector,explorer,foreman,league', '10120,10125,10130,10135,10121,10126,10131,10136', 1000, 0, 'A miner\'s coin for a sharp eye.', '"If you ever want honest work, there\'s always a pick going spare."', '', 0),
(475, 'tinker', 'tinker,mechano,clockwork,engineer,sprocket,evacuee,leper,f875,f64', '10140,10145,10150,10155,10141,10146,10151,10156', 1000, 0, 'A gnome\'s grateful coins.', '"If it whistles, don\'t touch it. If it doesn\'t whistle, definitely don\'t touch it."', '', 0),
(476, 'merchant', 'provisioner,tanner,peddler,angler,supplies,merchant,goods,trader,clothier,baker', '10160,10165,10170,10175,10161,10166,10171,10176', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Come back when the roads are open. I\'ll have better stock by then. Probably."', '', 0),
(477, 'folk', '*', '10180,10185,10190,10195,10181,10186,10191,10196', 500, 0, 'A few coins, given with thanks.', '"Mind how you go."', '', 0);

